<script setup>import {Head,Link,router} from '@inertiajs/vue3';import AppLayout from '../../Layouts/AppLayout.vue';const p=defineProps({questions:Object,courses:Array,filters:Object,statuses:Array});const change=()=>router.get(location.pathname,p.filters,{preserveState:true,replace:true});</script>
<template><AppLayout><Head title="پرسش‌ها"/><section class="rounded-2xl border bg-white p-5"><h1 class="text-xl font-bold">پرسش‌های درس‌ها</h1><div class="my-4 flex flex-wrap gap-3"><select v-model="filters.status" @change="change"><option value="">همه وضعیت‌ها</option><option v-for="s in statuses" :value="s.value">{{s.label}}</option></select><select v-model="filters.course_id" @change="change"><option value="">همه دوره‌ها</option><option v-for="c in courses" :value="c.id">{{c.title}}</option></select></div><div class="space-y-3"><Link v-for="q in questions.data" :key="q.id" :href="`/questions/${q.id}`" class="block rounded-xl border p-4 hover:border-teal-500"><div class="flex justify-between"><strong>{{q.subject||'بدون موضوع'}}</strong><span class="text-xs">{{q.status}}</span></div><p class="mt-1 text-sm">{{q.student.first_name}} {{q.student.last_name}} — {{q.lesson.course.title}} / {{q.lesson.title}}</p><p class="mt-2 line-clamp-2 text-sm text-slate-600">{{q.body}}</p><span v-if="q.staff_replies_count===0" class="mt-2 inline-block text-xs font-bold text-amber-700">بدون پاسخ</span></Link><p v-if="!questions.data.length" class="text-slate-500">پرسشی یافت نشد.</p></div><div class="mt-4 flex gap-2"><Link v-for="l in questions.links" :href="l.url||'#'" v-html="l.label" class="rounded border px-3 py-1"/></div></section></AppLayout></template>
